export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const n = p.count || 8;
  const r = p.radius || 2;
  const h = p.height || 0.45;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2 + ctx.range(-0.1, 0.1);
    const geo = new THREE.SphereGeometry(0.5, 8, 6);
    const shade = ctx.range(-0.04, 0.04);
    const c = new THREE.Color(p.color || '#b9bbc2').offsetHSL(0, 0, shade);
    const m = new THREE.Mesh(geo, ctx.mat(c));
    const s = ctx.range(0.85, 1.15);
    m.scale.set(0.6 * s, h * 1.1 * s, 0.45 * s);
    m.position.set(Math.cos(a) * r, h * 0.45, Math.sin(a) * r);
    m.rotation.y = -a + ctx.range(-0.4, 0.4);
    m.rotation.z = ctx.range(-0.1, 0.1);
    g.add(m);
  }
  return g;
}

export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const len = p.length || 25;
  const stride = p.stride || 0.75;
  const n = Math.floor(len / stride);
  const geo = new THREE.BoxGeometry(0.14, 0.02, 0.32);
  const mesh = new THREE.InstancedMesh(geo, ctx.mat(p.color || '#4a4c58'), n);
  const d = new THREE.Object3D();
  for (let i = 0; i < n; i++) {
    const side = i % 2 ? 1 : -1;
    d.position.set(side * 0.13 + ctx.range(-0.03, 0.03), 0.012, 0.5 + i * stride);
    d.rotation.set(0, ctx.range(-0.12, 0.12) + side * 0.05, 0);
    d.updateMatrix();
    mesh.setMatrixAt(i, d.matrix);
  }
  g.add(mesh);
  return g;
}

export function build(THREE, p, ctx) {
  const g = new THREE.Group();
  const shell = new THREE.Mesh(new THREE.SphereGeometry(0.5, 10, 8), ctx.mat(p.color || '#aab4c8', { transparent: true, opacity: 0.8, emissive: p.glow || '#6fa8ff', emissiveIntensity: 0.35 }));
  shell.scale.set(0.7, 0.58, 0.52);
  shell.position.y = 0.27;
  g.add(shell);
  const core = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 6), ctx.mat(p.glow || '#8ec5ff', { emissive: p.glow || '#6fa8ff', emissiveIntensity: 2.2 }));
  core.name = 'core';
  core.scale.set(0.3, 0.26, 0.22);
  core.position.y = 0.27;
  g.add(core);
  const crackMat = ctx.mat('#2a3040');
  let x = 0.12, y = 0.03;
  for (let i = 0; i < 5; i++) {
    const dy = 0.1, dx = ctx.range(-0.04, 0.04);
    const seg = new THREE.Mesh(new THREE.BoxGeometry(0.008, dy * 1.1, 0.008), crackMat);
    const f = 1 - Math.pow((y + dy / 2 - 0.27) / 0.29, 2);
    seg.position.set(x + dx / 2, y + dy / 2, 0.2 * Math.sqrt(Math.max(f, 0.1)) * 1.02);
    seg.rotation.z = -dx / dy;
    g.add(seg);
    x += dx; y += dy;
  }
  return g;
}
